#!/usr/bin/env bash
# The nine icon sheets for levels 11-100, one per tier, in the same style as the Stone Age sheet (art/raw/icons-t1.png).
# Each era changes the materials and adds one accent colour; hazard yellow stays in every sheet.
set -uo pipefail
cd "$(dirname "$0")"
style() { echo "A sprite sheet of TEN tiny pixel-art icons on a flat plain warm off-white background (#F4F0E7), arranged in a 5 by 2 grid with wide, even gaps between icons. Each icon is chunky low-resolution pixel art, about 24 by 24 art pixels, with big crisp square pixels, no anti-aliasing, no gradients, no text, no letters, no numbers. Same style as the attached sheet: cute and charming like tiny museum miniatures, near-black ink outlines. Limited palette: near-black ink (#0E0D0A), bone (#E8E1D3), warm stone grey (#8C8577), hazard yellow (#FFD400) as a small accent, plus $1. Theme: $2. Icons in order, top row left to right then bottom row:"; }
REF=../art/raw/icons-t1.png
gen() { [ -f "../art/raw/icons-t$1.png" ] && { echo "skip t$1"; return; }; ./gen.sh "icons-t$1" "$(style "$2" "$3") $4" "$REF"; }
gen 2 "ember orange (#C8642C)" "the age of fire: clay, charcoal, cave walls, embers and torches" "1) a clay tablet with carved lines and a small flame mark; 2) a small carved stone tablet hanging from a cord necklace; 3) a curved animal horn with sound lines coming out; 4) a bundle of bark pages tied with string; 5) two identical clay pots side by side; 6) a target drawn in charcoal on a flat rock; 7) a map drawn in charcoal on a flat stone with a dotted path; 8) three small carved figurines in a row; 9) a stone speech bubble with a question mark carved into it; 10) a cracked stone tablet with a fresh line carved under the crack."
gen 3 "warm wood brown (#8A5A34)" "the age of the wheel: wood, rope, stone wheels and early carts" "1) a wooden balance scale with two stones; 2) a cracked stone wheel next to a whole one; 3) a round wooden window frame showing a tiny landscape; 4) a clay seal stamp next to its imprint; 5) a wooden wheel with a curved arrow carved going backwards; 6) a bundle of different stone tools tied together with rope; 7) a wooden gate with two stones passing through; 8) a small cart parked beside a big cart; 9) three round stones lined up on a wooden rail; 10) a hollow log drum with sound marks."
gen 4 "bronze (#B0874A)" "the bronze age: bronze, copper and leather" "1) a bronze tool in an open leather pouch; 2) two linked bronze rings; 3) a bronze door standing slightly open; 4) a small boat with a bronze sail; 5) a bronze seal stamp; 6) a bronze sundial; 7) a bronze oil lamp with a flame; 8) a bronze vessel half filled with water with level marks; 9) two crossed bronze hammers; 10) a bronze bell with a rolled message tied to it."
gen 5 "iron blue-grey (#6E7480)" "the iron age: iron, the forge, anvils and chains" "1) an anvil with a freshly forged glowing blade; 2) three small iron helmets in a row; 3) an iron comb straightening wavy lines; 4) an iron shield; 5) an iron-bound wooden chest; 6) an iron ring holding one single key; 7) a tiny iron nail next to a long iron nail; 8) an iron frame of a small house, like a skeleton; 9) two hands passing an iron lantern; 10) an iron tree with three branches."
gen 6 "polished brass (#C09A4E)" "the age of steam: brass, gears, pipes and gauges" "1) a brass magnifying glass; 2) two different brass gears meshing; 3) a pair of brass goggles; 4) a brass bell with a question-mark tag; 5) a brass drafting compass on a sheet of paper; 6) a brass pressure gauge with the needle in the safe zone; 7) two tiny brass robots, one holding a paintbrush, one holding a wrench; 8) a brass steam engine puffing a small cloud; 9) a brass film camera on a tripod; 10) a small brass cage with a tiny steam robot inside."
gen 7 "pale electric blue (#7FB6E0)" "the electric age: light bulbs, wires, sparks and early radios" "1) an electric alarm clock; 2) a crescent moon next to a glowing light bulb; 3) a vintage telephone handset on a coiled cord; 4) a small cloud with a lightning bolt; 5) a checkered flag on a wire post; 6) a coiled cable forming a loop; 7) a conveyor belt carrying three light bulbs; 8) four light bulbs in a row, only one lit; 9) two plugs facing each other with a spark between them; 10) a glowing vacuum tube radio."
gen 8 "circuit green (#3E8E5A)" "the silicon age: microchips, circuit boards and tiny robots" "1) five tiny microchips in a row; 2) a conductor's baton over a small circuit board; 3) a big microchip wired to a small microchip; 4) three tiny robots wearing name badges; 5) a circuit trace with arrows running through three nodes; 6) two tiny robots boxing; 7) three magnifying glasses over one microchip; 8) a staircase made of microchips; 9) a microchip with a check mark etched on it; 10) a USB stick."
gen 9 "deep space navy (#2C3E6B)" "the space age: rockets, satellites, astronauts and radar" "1) a rocket on a test stand; 2) a satellite sending out signal waves; 3) a small space station with a speech bubble; 4) an open rocket model kit with parts; 5) an astronaut helmet with a small face reflected in the visor; 6) two satellites linked by a beam; 7) a radar dish; 8) a clipboard with a launch checklist; 9) a small planetary rover; 10) a boot print on the moon next to the matching boot."
gen 10 "no extra colour, only the base palette with a little more hazard yellow" "full circle, back to the stone age, but calm and wise like a zen garden: smooth stones, sand, a single careful mark" "1) a small broom sweeping a few pebbles away; 2) a freshly raked zen sand garden square; 3) one smooth balanced stone; 4) a simple stone arch; 5) a grey stone with one bright yellow vein; 6) an hourglass made of stone; 7) two small stone figures, one pointing at a tablet for the other; 8) a raised open stone palm; 9) a very long unrolled scroll with a small reading stone on it; 10) a magnifying glass over one single glowing yellow pixel on a stone tablet."
